_PRIORITY_RANK = {"P0": 0, "P1": 1, "P2": 2, "P3": 3}

def _admin_redirect(request: Request): return v2._admin_redirect(request)
def _find_route(path: str, method: str = "GET"):
    for route in core.app.routes:
        if isinstance(route, APIRoute) and route.path == path and method in route.methods: return route
    return None

def _count(db: Session, model, *conds) -> int:
    stmt = select(func.count(model.id))
    if conds: stmt = stmt.where(*conds)
    return int(db.scalar(stmt) or 0)

def _badge_class(value: str) -> str:
    clean = str(value or "").strip().upper().replace("_", " ")
    if clean == "P0": return "p0"
    if clean == "P1": return "p1"
    if clean == "P2": return "p2"
    if "CEO" in clean: return "ceo"
    if clean == "AUTO": return "auto"
    return "approval"

def _safe_dt(value):
    if value is None: return datetime.min.replace(tzinfo=timezone.utc)
    if value.tzinfo is None: return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)

def _status_class(status: str) -> str: return "ok" if status in {"Connected", "Readable", "Writable"} else "wait"
def _status_label(status: str) -> str: return v2._status_ar(status or "Needs Integration")

def _lane_html(title: str, items: list[dict]) -> str:
    parts = []
    for item in items[:3]:
        badge = f"<span class='mc-badge {core.esc(item.get('badge_class') or 'approval')}'>{core.esc(item.get('badge'))}</span>" if item.get("badge") else ""
        parts.append(f"<div class='mc-item'><strong>{core.esc(item['title'])}</strong><div class='mc-meta'><span>{core.esc(item.get('source') or 'Pakgat AI')}</span><span>·</span><span>{core.esc(item.get('freshness') or '—')}</span>{badge}</div></div>")
    return f"<section class='mc-lane'><div class='mc-lane-title'>{core.esc(title)}</div>{''.join(parts) or '<div class=\'mc-empty\'>لا توجد عناصر فعلية في هذه الفئة الآن.</div>'}</section>"

def _activity_entry(ts, source: str, text: str) -> dict: return {"ts": _safe_dt(ts), "source": source, "text": text, "freshness": freshness_label(ts)}

@core.app.post("/admin/company/command")
async def mission_control_command(request: Request, db: Session = Depends(core.get_db)):
    """AI Command Bar: safe allow-listed navigation and internal AUTO-safe cycle only."""
    redirect = _admin_redirect(request)
    if redirect: return redirect
    form = await request.form()
    target, message = resolve_command(str(form.get("command") or ""))
    if target == "RUN_COMPANY":
        run_connected_company_cycle(db); core.log_event(db, "mission_control_command", details="target=RUN_COMPANY")
        return RedirectResponse("/admin/company?command=run", status_code=303)
    if target:
        core.log_event(db, "mission_control_command", details=f"target={target}")
        return RedirectResponse(target, status_code=303)
    core.log_event(db, "mission_control_command_unknown", details=f"message={message[:180]}")
    return RedirectResponse("/admin/company?command=unknown", status_code=303)

def mission_control_dashboard(request: Request, db: Session = Depends(core.get_db)):
    redirect = _admin_redirect(request)
    if redirect: return redirect
    snapshot = ai_company.collect_company_snapshot(db)
    orders = _count(db, SallaOrderSnapshot); product_lines = _count(db, SallaOrderItemSnapshot)
    new_opps = _count(db, ai_company.CompanyOpportunity, ai_company.CompanyOpportunity.status == "new")
    store_issues = _count(db, StoreOpsIssue, StoreOpsIssue.status == "open")
    source_summary = ai_company_sources.source_summary(db); source_rows = source_summary["rows"]; source_counts = source_summary["counts"]
    usable_states = {"Connected", "Readable", "Writable"}; usable_sources = sum(int(source_counts.get(k, 0)) for k in usable_states)
    source_map = {row.source: row.status for row in source_rows}
    core_ready = all(source_map.get(name) in usable_states for name in ("Google Compute Engine", "PostgreSQL")); core_status = "Operational" if core_ready else "Needs Attention"
    readiness = summarize_system_statuses(card[2] for card in v2.SYSTEM_CARDS)
    ga_state = source_map.get("Google Analytics", "Needs Integration"); sc_state = source_map.get("Google Search Console", "Needs Integration"); whats_state = source_map.get("WhatsLoop", "Needs Integration")
    approvals = list(db.scalars(select(CompanyApproval).where(CompanyApproval.status == "pending").order_by(CompanyApproval.created_at.desc()).limit(8)).all())
    approvals = sorted(approvals, key=lambda r: approval_weight(r.priority, r.approval_level, r.created_at), reverse=True)
    alerts = list(db.scalars(select(ai_company.CompanyAlert).where(ai_company.CompanyAlert.status == "open").order_by(ai_company.CompanyAlert.created_at.desc()).limit(8)).all())
    alerts = sorted(alerts, key=lambda r: (_PRIORITY_RANK.get(str(r.severity).upper(), 9), -_safe_dt(r.created_at).timestamp()))
    opportunities = list(db.scalars(select(ai_company.CompanyOpportunity).where(ai_company.CompanyOpportunity.status.in_(["new","review","approved","active"])).order_by(ai_company.CompanyOpportunity.updated_at.desc()).limit(12)).all())
    opportunity_rows = [(r, opportunity_attention_score(r.score, r.priority, r.status, r.created_at)) for r in opportunities]; opportunity_rows.sort(key=lambda x:x[1], reverse=True)
    tasks = list(db.scalars(select(ai_company.CompanyTask).where(ai_company.CompanyTask.status == "open").order_by(ai_company.CompanyTask.created_at.desc()).limit(6)).all())
    decisions = list(db.scalars(select(CompanyDecision).order_by(CompanyDecision.created_at.desc()).limit(4)).all())
    health_history = list(db.scalars(select(ai_company.CompanyMetricSnapshot).where(ai_company.CompanyMetricSnapshot.metric_group == "company_health").order_by(ai_company.CompanyMetricSnapshot.created_at.desc()).limit(8)).all()); health_history.reverse()
    spark = sparkline_points([r.score for r in health_history if r.score is not None])
    merchant_total = _count(db, CompanyLead, CompanyLead.lead_type == "merchant")
    merchant_qualified = _count(db, CompanyLead, CompanyLead.lead_type == "merchant", CompanyLead.status.in_(["qualified","contact_ready"]))
    merchant_contacted = _count(db, CompanyLead, CompanyLead.lead_type == "merchant", CompanyLead.status.in_(["contacted","replied"]))
    merchant_negotiating = _count(db, CompanyLead, CompanyLead.lead_type == "merchant", CompanyLead.status == "negotiating")
    merchant_live = _count(db, CompanyLead, CompanyLead.lead_type == "merchant", CompanyLead.status == "live")
    supplier_leads = list(db.scalars(select(CompanyLead).where(CompanyLead.lead_type == "supplier").order_by(CompanyLead.updated_at.desc()).limit(5)).all())
