_base_layout_wrap = v2._layout_wrap

def mission_control_layout_wrap(html: str, path: str) -> str:
    """AI Core + approved Pakgat logo decoration for Mission Control home only."""
    rendered = _base_layout_wrap(html, path)
    if path.rstrip("/") != "/admin/company": return rendered
    status_match = re.search(r"data-mc-core-status='([^']*)'", rendered); source_match = re.search(r"data-mc-source-count='([^']*)'", rendered)
    status = status_match.group(1) if status_match else "Operational"; source_count = source_match.group(1) if source_match else "0"
    old_logo = "<div class='ai-logo'><strong>بكجات AI</strong><span>شركة بكجات الذكية · مركز التحكم</span></div>"
    new_logo = f"<!-- AI Core --><div class='mc-ai-core'><img class='mc-brand-logo' src='{PAKGAT_LOGO_DATA_URI}' alt='Pakgat'><div class='mc-core-state'><span><i class='mc-ai-pulse'></i><strong>{core.esc(status)}</strong></span><span>{core.esc(source_count)} sources ready</span></div></div>"
    rendered = rendered.replace(old_logo, new_logo, 1)
    old_foot = "<div class='ai-sidebar-foot'>PA · Pakgat AI<br>مدير الشركة الذكي</div>"; new_foot = "<div class='mc-operator'><div class='mc-operator-card'><span class='mc-avatar'>PA</span><div><strong>Pakgat AI</strong><span>Mission Control Online</span></div></div></div>"
    rendered = rendered.replace(old_foot, new_foot, 1)
    return rendered.replace("</head>", f"<style>{MISSION_CSS}</style></head>", 1)

v2._layout_wrap = mission_control_layout_wrap
